from typing import List

class Solution:
    def minOperations(self, nums: List[int], x: int, k: int) -> int:
        N = len(nums)
        unique_nums = sorted(set(nums))
        M = len(unique_nums)
        val_to_idx = {val: i + 1 for i, val in enumerate(unique_nums)}

        bit_cnt = [0] * (M + 1)
        bit_sum = [0] * (M + 1)

        max_pow = 0
        while (1 << max_pow) <= M:
            max_pow += 1

        def add(val: int, delta: int) -> None:
            idx = val_to_idx[val]
            while idx <= M:
                bit_cnt[idx] += delta
                bit_sum[idx] += val * delta
                idx += idx & -idx

        def sum_smallest(t: int) -> int:
            curr_idx = 0
            cnt = 0
            s = 0
            for p in range(max_pow - 1, -1, -1):
                next_idx = curr_idx + (1 << p)
                if next_idx <= M and cnt + bit_cnt[next_idx] <= t:
                    curr_idx = next_idx
                    cnt += bit_cnt[curr_idx]
                    s += bit_sum[curr_idx]
            if cnt < t:
                s += (t - cnt) * unique_nums[curr_idx]
            return s

        for i in range(x - 1):
            add(nums[i], 1)

        C = [0] * (N - x + 1)
        k1 = x // 2
        k2 = (x + 1) // 2
        total_sum = sum(nums[:x - 1])

        for i in range(N - x + 1):
            add(nums[i + x - 1], 1)
            total_sum += nums[i + x - 1]

            sum1 = sum_smallest(k1)
            sum2 = sum_smallest(k2)
            C[i] = total_sum - sum1 - sum2

            add(nums[i], -1)
            total_sum -= nums[i]

        dp = [0] * (N + x + 1)

        for j in range(1, k + 1):
            new_dp = [float("inf")] * (N + x + 1)
            for i in range(N - j * x, -1, -1):
                new_dp[i] = min(new_dp[i + 1], C[i] + dp[i + x])
            dp = new_dp

        return int(dp[0])
